    constructor(address payable target) payable {
        selfdestruct(target);
    }
}

contracts/KENOAutoBurn.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title KENOAutoBurn
 * @author Kenostod Blockchain Academy LLC
 * @notice Receives BNB from the King's Shield Aegis Tax cross-chain relay,
 *         auto-buys KENO via PancakeSwap, and burns it to the dead address.
 *
 * Flywheel:
 *   SHIELD bonds sold → SHIELD/SOL LP grows → Aegis Tax collected (Solana)
 *   → Cross-chain relay bridges to BSC → this contract buys + burns KENO
 *   → KENO supply ↓, price ↑ → SHIELD narrative strengthens → loop continues
 *
 * Authorized relayers are whitelisted — only they can trigger burns.
 * Anyone can contribute BNB to the burn fund via receive().
 */
contract KENOAutoBurn is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ── Constants ─────────────────────────────────────────────────────────
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;

    // PancakeSwap V2 Router on BSC Mainnet
    address public constant PANCAKE_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address public constant WBNB           = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;

    // ── State ─────────────────────────────────────────────────────────────
    IERC20 public immutable kenoToken;

    /// @notice Max slippage on PancakeSwap swap (default 500 = 5%)
    uint256 public maxSlippageBps = 500;

    /// @notice Total KENO burned through this contract (ever)
    uint256 public totalKenoBurned;

    /// @notice Total BNB used for burns (ever)
    uint256 public totalBnbUsed;

    /// @notice Number of burn events executed
    uint256 public burnCount;

    /// @notice Addresses authorized to trigger burns (cross-chain relayers)
    mapping(address => bool) public authorizedRelayers;

    // ── Events ────────────────────────────────────────────────────────────
    event KenoBurned(
        address indexed triggeredBy,
        uint256 bnbIn,
        uint256 kenoBurned,
        uint256 totalBurned
    );
    event RelayerAdded(address relayer);
    event RelayerRemoved(address relayer);
    event SlippageUpdated(uint256 newBps);
    event BnbWithdrawn(uint256 amount);

    // ── Modifiers ─────────────────────────────────────────────────────────
    modifier onlyRelayerOrOwner() {
        require(
            authorizedRelayers[msg.sender] || msg.sender == owner(),
            "Not authorized"
        );
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────
    constructor(
        address _kenoToken,
        address _owner
    ) Ownable(_owner) {
        require(_kenoToken != address(0), "Zero: kenoToken");
        kenoToken = IERC20(_kenoToken);
    }

    // ── Core: Burn ────────────────────────────────────────────────────────

    /**
     * @notice Buy KENO with all BNB held in this contract and burn it.
     *         Called by authorized cross-chain relayers after bridging Aegis Tax.
     * @param minKenoOut Minimum KENO to receive (slippage guard).
     */
    function executeBurn(uint256 minKenoOut)
        external
        nonReentrant
        whenNotPaused
        onlyRelayerOrOwner
    {
        uint256 bnbBalance = address(this).balance;
        require(bnbBalance > 0, "No BNB to burn");

        uint256 kenoBefore = kenoToken.balanceOf(address(this));

        // Swap BNB → KENO via PancakeSwap V2
        address[] memory path = new address[](2);
        path[0] = WBNB;
        path[1] = address(kenoToken);

        IPancakeRouter(PANCAKE_ROUTER).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: bnbBalance
        }(
            minKenoOut,
            path,
            address(this),
            block.timestamp + 300 // 5-minute deadline
        );

        uint256 kenoReceived = kenoToken.balanceOf(address(this)) - kenoBefore;
        require(kenoReceived > 0, "No KENO received");

        // Burn — transfer to dead address
        kenoToken.safeTransfer(DEAD, kenoReceived);

        totalKenoBurned += kenoReceived;
        totalBnbUsed    += bnbBalance;
        burnCount       += 1;

        emit KenoBurned(msg.sender, bnbBalance, kenoReceived, totalKenoBurned);
    }

    /**
     * @notice Burn a specific BNB amount (partial burn from balance).
     * @param bnbAmount  BNB to use for this burn.
     * @param minKenoOut Minimum KENO to receive.
     */
    function executeBurnAmount(uint256 bnbAmount, uint256 minKenoOut)
        external
        nonReentrant
        whenNotPaused
        onlyRelayerOrOwner
    {
        require(bnbAmount > 0,                     "Amount must be > 0");
        require(address(this).balance >= bnbAmount, "Insufficient BNB balance");

        uint256 kenoBefore = kenoToken.balanceOf(address(this));

        address[] memory path = new address[](2);
        path[0] = WBNB;
        path[1] = address(kenoToken);

        IPancakeRouter(PANCAKE_ROUTER).swapExactETHForTokensSupportingFeeOnTransferTokens{
            value: bnbAmount
        }(
            minKenoOut,
            path,
            address(this),
            block.timestamp + 300
        );

        uint256 kenoReceived = kenoToken.balanceOf(address(this)) - kenoBefore;
        require(kenoReceived > 0, "No KENO received");

        kenoToken.safeTransfer(DEAD, kenoReceived);

        totalKenoBurned += kenoReceived;
        totalBnbUsed    += bnbAmount;
        burnCount       += 1;

        emit KenoBurned(msg.sender, bnbAmount, kenoReceived, totalKenoBurned);
    }

    // ── View ──────────────────────────────────────────────────────────────

    /// @notice Preview: how much KENO would be bought with current BNB balance.
    function getBurnQuote() external view returns (uint256 kenoOut) {
        uint256 bnb = address(this).balance;
        if (bnb == 0) return 0;
        address[] memory path = new address[](2);
        path[0] = WBNB;
        path[1] = address(kenoToken);
        try IPancakeRouter(PANCAKE_ROUTER).getAmountsOut(bnb, path)
            returns (uint256[] memory amounts)
        {
            kenoOut = amounts[1];
        } catch {
            kenoOut = 0;
        }
    }

    /// @notice Stats summary.
    function stats() external view returns (
        uint256 _totalBurned,
        uint256 _totalBnbUsed,
        uint256 _burnCount,
        uint256 _pendingBnb
    ) {
        return (totalKenoBurned, totalBnbUsed, burnCount, address(this).balance);
    }

    // ── Owner ─────────────────────────────────────────────────────────────

    function addRelayer(address relayer) external onlyOwner {
        require(relayer != address(0), "Zero address");
        authorizedRelayers[relayer] = true;
        emit RelayerAdded(relayer);
    }

    function removeRelayer(address relayer) external onlyOwner {
        authorizedRelayers[relayer] = false;
        emit RelayerRemoved(relayer);
    }

    function setMaxSlippage(uint256 bps) external onlyOwner {
        require(bps <= 3000, "Max 30%");
        maxSlippageBps = bps;
        emit SlippageUpdated(bps);
    }

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /// @notice Emergency: withdraw BNB if something goes wrong.
    function emergencyWithdrawBnb() external onlyOwner {
        uint256 bal = address(this).balance;
        require(bal > 0, "No BNB");
        (bool sent,) = payable(owner()).call{value: bal}("");
        require(sent, "Transfer failed");
        emit BnbWithdrawn(bal);
    }

    /// @notice Accept BNB from relay bridges, wallets, or direct contributions.
    receive() external payable {}
}

// ── Interface: PancakeSwap V2 Router ─────────────────────────────────────
interface IPancakeRouter {
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable;

    function getAmountsOut(uint256 amountIn, address[] calldata path)
        external
        view
        returns (uint256[] memory amounts);
}

contracts/KENOBondingCurve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title KENOBondingCurve
 * @author Kenostod Blockchain Academy LLC
 * @notice Linear bonding curve for continuous KENO token distribution on BSC.
 *
 * Price Formula (Constitutional Law 3 — Golden Ratio scaling):
 *   price(sold) = BASE_PRICE + SLOPE * sold / 1e18
 *   where `sold` is total KENO distributed in wei (18 decimals)
 *
 * Buy cost for `amount` tokens when `sold` already distributed:
 *   cost = BASE_PRICE * amount / 1e18
 *        + SLOPE * (2 * sold * amount + amount²) / (2 * 1e36)
 *
 * Sell proceeds (inverse integral):
 *   proceeds = BASE_PRICE * amount / 1e18
 *            + SLOPE * amount * (2 * sold - amount) / (2 * 1e36)
 *
 * Fees:
 *   - Buy:  3% → 50% to UTL fee accumulator, 50% to treasury
 *   - Sell: 5% → 50% to UTL fee accumulator, 50% to treasury
 *
 * The contract holds a KENO allocation deposited by the owner.
 * BNB reserves back every token sold through the curve.
 */
contract KENOBondingCurve is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------

    /// @notice Starting price: 0.000001 BNB per KENO (~$0.0006 at $600/BNB)
    uint256 public constant BASE_PRICE = 1e12;

    /// @notice Slope: price rises 20000 wei BNB per full KENO of additional supply
    ///         At 50M KENO sold → price doubles. Derived from φ (Golden Ratio ≈ 1.618)
    ///         scaled to fit the target curve: SLOPE = floor(BASE_PRICE / (φ * 30_000_000))
    uint256 public constant SLOPE = 20_000;

    uint256 public constant BUY_FEE_BPS  = 300;   // 3.0%
    uint256 public constant SELL_FEE_BPS = 500;   // 5.0%
    uint256 public constant UTL_FEE_SHARE = 50;   // 50% of fee → UTL accumulator
    uint256 public constant BPS_BASE = 10_000;
    uint256 internal constant PREC = 1e18;

    // -------------------------------------------------------------------------
    // State
    // -------------------------------------------------------------------------

    IERC20  public immutable kenoToken;

    /// @notice Receives 50% of all fees — accumulated in BNB for UTL Protocol
    address public utlFeeAccumulator;

    /// @notice Receives 50% of all fees — project treasury
    address public treasury;

    /// @notice Total KENO sold through this curve (wei, 18 dec)
    uint256 public tokensSold;

    /// @notice BNB locked as reserve backing sold tokens
    uint256 public bnbReserves;

    /// @notice Total KENO deposited into this contract for sale
    uint256 public allocation;

    // -------------------------------------------------------------------------
    // Events
    // -------------------------------------------------------------------------

    event TokensPurchased(
        address indexed buyer,
        uint256 bnbIn,
        uint256 kenoOut,
        uint256 newPrice,
        uint256 fee
    );
    event TokensSold(
        address indexed seller,
        uint256 kenoIn,
        uint256 bnbOut,
        uint256 newPrice,
        uint256 fee
    );
    event AllocationAdded(uint256 amount, uint256 totalAllocation);
    event UtlFeeAccumulatorUpdated(address newAccumulator);
    event TreasuryUpdated(address newTreasury);
    event ExcessBnbWithdrawn(uint256 amount);
    event ExcessKenoWithdrawn(uint256 amount);

    // -------------------------------------------------------------------------
    // Constructor
    // -------------------------------------------------------------------------

    constructor(
        address _kenoToken,
        address _utlFeeAccumulator,
        address _treasury,
        address _owner
    ) Ownable(_owner) {
        require(_kenoToken          != address(0), "Zero: kenoToken");
        require(_utlFeeAccumulator  != address(0), "Zero: utlFeeAccumulator");
        require(_treasury           != address(0), "Zero: treasury");
        kenoToken          = IERC20(_kenoToken);
        utlFeeAccumulator  = _utlFeeAccumulator;
        treasury           = _treasury;
    }

    // -------------------------------------------------------------------------
    // Core: Buy
    // -------------------------------------------------------------------------

    /**
     * @notice Buy KENO with BNB.
     * @param minKenoOut Minimum KENO to receive (slippage guard).
     */
    function buy(uint256 minKenoOut) external payable nonReentrant whenNotPaused {
        require(msg.value > 0, "Send BNB to buy KENO");

        uint256 fee        = (msg.value * BUY_FEE_BPS) / BPS_BASE;
        uint256 bnbForCurve = msg.value - fee;

        uint256 available = allocation - tokensSold;
        require(available > 0, "No KENO available");

        uint256 kenoOut = _bnbToTokens(bnbForCurve, tokensSold, available);
        require(kenoOut > 0,          "Too little BNB");
        require(kenoOut >= minKenoOut, "Slippage: insufficient KENO out");

        tokensSold  += kenoOut;
        bnbReserves += bnbForCurve;

        _distributeFee(fee);
        kenoToken.safeTransfer(msg.sender, kenoOut);

        emit TokensPurchased(msg.sender, msg.value, kenoOut, _priceAt(tokensSold), fee);
    }

    // -------------------------------------------------------------------------
    // Core: Sell
    // -------------------------------------------------------------------------

    /**
     * @notice Sell KENO back to the curve for BNB.
     * @param kenoAmount Amount of KENO to sell (18 dec).
     * @param minBnbOut  Minimum BNB to receive (slippage guard).
     */
    function sell(uint256 kenoAmount, uint256 minBnbOut)
        external
        nonReentrant
        whenNotPaused
    {
        require(kenoAmount > 0,             "Amount must be > 0");
        require(kenoAmount <= tokensSold,   "Exceeds curve supply");

        uint256 grossBnb = _tokensToBnbSell(kenoAmount, tokensSold);
        uint256 fee      = (grossBnb * SELL_FEE_BPS) / BPS_BASE;
        uint256 bnbOut   = grossBnb - fee;

        require(bnbOut >= minBnbOut,             "Slippage: insufficient BNB out");
        require(address(this).balance >= grossBnb, "Insufficient BNB reserves");

        tokensSold  -= kenoAmount;
        bnbReserves -= grossBnb;

        kenoToken.safeTransferFrom(msg.sender, address(this), kenoAmount);
        _distributeFee(fee);

        (bool sent,) = payable(msg.sender).call{value: bnbOut}("");
        require(sent, "BNB transfer failed");

        emit TokensSold(msg.sender, kenoAmount, bnbOut, _priceAt(tokensSold), fee);
    }

    // -------------------------------------------------------------------------
    // View: Quotes
    // -------------------------------------------------------------------------

    /// @notice Current spot price in wei BNB per full KENO token.
    function currentPrice() external view returns (uint256) {
        return _priceAt(tokensSold);
    }

    /// @notice Quote KENO out and fee for a given BNB input.
    function getBuyQuote(uint256 bnbIn)
        external
        view
        returns (uint256 kenoOut, uint256 fee)
    {
        fee     = (bnbIn * BUY_FEE_BPS) / BPS_BASE;
        uint256 bnbForCurve = bnbIn - fee;
        uint256 available = allocation > tokensSold ? allocation - tokensSold : 0;
        kenoOut = _bnbToTokens(bnbForCurve, tokensSold, available);
    }

    /// @notice Quote BNB out and fee for a given KENO sell amount.
    function getSellQuote(uint256 kenoAmount)
        external
        view
        returns (uint256 bnbOut, uint256 fee)
    {
        if (kenoAmount > tokensSold) return (0, 0);
        uint256 gross = _tokensToBnbSell(kenoAmount, tokensSold);
        fee    = (gross * SELL_FEE_BPS) / BPS_BASE;
        bnbOut = gross - fee;
    }

    /// @notice How many KENO remain available to buy.
    function availableKeno() external view returns (uint256) {
        return allocation > tokensSold ? allocation - tokensSold : 0;
    }

    // -------------------------------------------------------------------------
    // Internal Math
    // -------------------------------------------------------------------------

    /// @dev price(sold) = BASE_PRICE + SLOPE * sold / 1e18
    function _priceAt(uint256 sold) internal pure returns (uint256) {
        return BASE_PRICE + (SLOPE * sold) / PREC;
    }

    /**
     * @dev BNB cost to buy `amount` tokens when `sold` already distributed.
     *      Integral of price from sold to sold+amount:
     *      = BASE_PRICE * amount / 1e18
     *      + SLOPE * (2*sold*amount + amount²) / (2 * 1e36)
     */
    function _tokensToBnbBuy(uint256 amount, uint256 sold)
        internal
        pure
        returns (uint256)
    {
        uint256 linear    = (BASE_PRICE * amount) / PREC;
        uint256 quadratic = (SLOPE * ((2 * sold * amount) / PREC + (amount * amount) / PREC))
                            / (2 * PREC);
        return linear + quadratic;
    }

    /**
     * @dev BNB proceeds from selling `amount` tokens when `sold` is current supply.
     *      Integral of price from sold-amount to sold:
     *      = BASE_PRICE * amount / 1e18
     *      + SLOPE * amount * (2*sold - amount) / (2 * 1e36)
     */
    function _tokensToBnbSell(uint256 amount, uint256 sold)
        internal
        pure
        returns (uint256)
    {
        uint256 linear    = (BASE_PRICE * amount) / PREC;
        uint256 quadratic = (SLOPE * amount * (2 * sold - amount)) / (2 * PREC * PREC);
        return linear + quadratic;
    }

    /**
     * @dev Binary search: given `bnb`, find max tokens purchasable.
     *      Upper bound capped at `available` to never exceed allocation.
     */
    function _bnbToTokens(
        uint256 bnb,
        uint256 sold,
        uint256 available
    ) internal pure returns (uint256) {
        if (available == 0 || bnb == 0) return 0;

        uint256 lo = 0;
        // rough upper bound: at base price, max tokens
        uint256 hi = (bnb * PREC) / BASE_PRICE;
        if (hi > available) hi = available;

        for (uint256 i = 0; i < 128; i++) {
            uint256 mid  = (lo + hi) / 2;
            if (mid == 0) break;
            uint256 cost = _tokensToBnbBuy(mid, sold);
            if (cost <= bnb) {
                lo = mid;
            } else {
                hi = mid;
            }
            if (hi <= lo + 1e9) break; // ~1 micro-KENO precision
        }
        return lo;
    }

    // -------------------------------------------------------------------------
    // Internal: Fee Distribution
    // -------------------------------------------------------------------------

    function _distributeFee(uint256 fee) internal {
        if (fee == 0) return;
        uint256 utlShare      = (fee * UTL_FEE_SHARE) / 100;
        uint256 treasuryShare = fee - utlShare;

        if (utlShare > 0 && utlFeeAccumulator != address(0)) {
            (bool s1,) = payable(utlFeeAccumulator).call{value: utlShare}("");
            if (!s1) treasuryShare += utlShare;
        }
        if (treasuryShare > 0) {
            (bool s2,) = payable(treasury).call{value: treasuryShare}("");
            require(s2, "Treasury transfer failed");
        }
    }

    // -------------------------------------------------------------------------
    // Owner: Administration
    // -------------------------------------------------------------------------

    /**
     * @notice Deposit KENO into the bonding curve for sale.
     *         Owner must approve this contract to transfer `amount` KENO first.
     */
    function addAllocation(uint256 amount) external onlyOwner {
        require(amount > 0, "Zero amount");
        allocation += amount;
        kenoToken.safeTransferFrom(msg.sender, address(this), amount);
        emit AllocationAdded(amount, allocation);
    }

    function setUtlFeeAccumulator(address _acc) external onlyOwner {
        require(_acc != address(0), "Zero address");
        utlFeeAccumulator = _acc;
        emit UtlFeeAccumulatorUpdated(_acc);
    }

    function setTreasury(address _t) external onlyOwner {
        require(_t != address(0), "Zero address");
        treasury = _t;
        emit TreasuryUpdated(_t);
    }

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    /**
     * @notice Withdraw BNB in excess of reserves (e.g. direct donations).
     *         Never touches the BNB backing sold tokens.
     */
    function withdrawExcessBnb() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > bnbReserves, "No excess BNB");
        uint256 excess = balance - bnbReserves;
        (bool sent,) = payable(owner()).call{value: excess}("");
        require(sent, "Transfer failed");
        emit ExcessBnbWithdrawn(excess);
    }

    /**
     * @notice Withdraw KENO not yet sold (unsold allocation).
     */
    function withdrawExcessKeno() external onlyOwner {
        uint256 unsold = allocation - tokensSold;
        require(unsold > 0, "No unsold KENO");
        allocation -= unsold;
        kenoToken.safeTransfer(owner(), unsold);
        emit ExcessKenoWithdrawn(unsold);
    }

    receive() external payable {}
}

contracts/KENOPOLBond.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title KENOPOLBond
 * @author Kenostod Blockchain Academy LLC
 * @notice Protocol-Owned Liquidity bonding contract — OlympusDAO v2 mechanics
 *         adapted for the KENO ecosystem on BSC.
 *
 * ─── HOW IT WORKS ────────────────────────────────────────────────────────────
 *
 *  1. User approves this contract to spend their KENO/BNB LP tokens.
 *  2. User calls deposit(lpAmount, maxPrice, depositor).
 *  3. Contract values the LP at fair market price, applies a discount (5–10%
 *     below KENO spot), and quotes how much KENO they will receive.
 *  4. LP tokens are transferred permanently to the TREASURY — no counterparty
 *     can ever withdraw them. The treasury owns the liquidity forever.
 *  5. KENO payout vests linearly over VESTING_PERIOD (5 days by default).
 *  6. User calls redeem() at any time to claim whatever has vested so far.
 *
 * ─── 7 CONSTITUTIONAL LAWS ───────────────────────────────────────────────────
 *
 *  1. Kaprekar  — all dust from integer division flows to the depositor, never lost.
 *  2. Benford   — bond volume tracked per-block; owner can inspect for anomalies.
 *  3. GoldenRatio — BCV decays toward φ-floor; discount approaches φ-ratio (1.618%)
 *                   baseline minimum so early bonders are always rewarded.
 *  4. Nash      — BCV auto-adjusts each block to maintain the equilibrium discount
 *                 window (5–10%). If demand is too high, discount shrinks; too low,
 *                 discount widens — keeping participation always the dominant strategy.
 *  5. Euler     — vesting is continuous: payout accrues every second, not in tranches.
 *  6. Ramanujan — wallets that bond past 1729 KENO cumulative receive a silent 1.729%
 *                 bonus on that bond (the Hardy-Ramanujan taxi-cab constant).
 *  7. Inversion — LP flows DOWN into the treasury (a permanent community asset),
 *                 not UP to a founder who can exit. Value compounds for all holders.
 *
 * ─── KEY NUMBERS (rooted in Kaprekar's 6174) ─────────────────────────────────
 *
 *  VESTING_PERIOD  = 432,000 seconds (5 days)   — 6174 × 70 ≈ 432,180
 *  MAX_DISCOUNT_BPS = 1000 (10%)
 *  MIN_DISCOUNT_BPS = 162  (≈ 1.618% — φ floor, Law 3)
 *  RAMANUJAN_THRESHOLD = 1729 × 1e18             — Law 6
 *  RAMANUJAN_BONUS_BPS = 173                     — 1.73%, rooted in 1729
 *  MAX_PAYOUT_BPS      = 400                     — 4% of KENO supply per bond (safety cap)
 */
contract KENOPOLBond is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    // ─── Interfaces ──────────────────────────────────────────────────────────

    IERC20 public immutable kenoToken;   // KENO v2 on BSC
    IERC20 public immutable lpToken;     // KENO/BNB PancakeSwap LP token
    address public immutable treasury;   // LP tokens flow here permanently

    // ─── Constants (Constitutional) ──────────────────────────────────────────

    uint256 public constant VESTING_PERIOD    = 432_000;   // 5 days in seconds (Law 1, 6174-rooted)
    uint256 public constant MAX_DISCOUNT_BPS  = 1_000;     // 10% max discount
    uint256 public constant MIN_DISCOUNT_BPS  = 162;       // φ floor 1.618% (Law 3)
    uint256 public constant BPS_BASE          = 10_000;
    uint256 public constant RAMANUJAN_THRESHOLD = 1_729 * 1e18; // Law 6
    uint256 public constant RAMANUJAN_BONUS_BPS = 173;     // 1.73% silent bonus
    uint256 public constant MAX_PAYOUT_BPS    = 400;       // 4% of supply per bond

    // ─── BCV (Bond Control Variable) — Nash auto-tune ────────────────────────
    // Bond price (in LP-value units per KENO) = BCV × KENO supply / 1e18
    // Higher BCV → lower discount.  Lower BCV → higher discount.
    // Target: discount stays in [MIN_DISCOUNT_BPS, MAX_DISCOUNT_BPS].

    uint256 public bcv;                 // Bond Control Variable (scaled ×1e18)
    uint256 public bcvDecay;            // BPS per block BCV decays when demand is low
    uint256 public lastBcvBlock;        // last block BCV was adjusted
    uint256 public targetDebtRatio;     // target outstanding KENO bonds / total supply (BPS)

    // ─── Supply & Debt ───────────────────────────────────────────────────────

    uint256 public kenoAvailable;       // KENO deposited by owner for bond payouts
    uint256 public totalDebt;           // KENO promised but not yet vested (raw units)
    uint256 public totalLpDeposited;    // cumulative LP permanently sent to treasury
    uint256 public totalKenoPaid;       // cumulative KENO fully vested + claimed

    // ─── Per-depositor bond state ─────────────────────────────────────────────

    struct Bond {
        uint256 payout;         // total KENO owed for this bond
        uint256 vested;         // KENO already claimed from this bond
        uint256 lastRedeemed;   // timestamp of last redeem (or deposit)
        uint256 start;          // bond creation timestamp
    }

    mapping(address => Bond)    public bonds;
    mapping(address => uint256) public totalBonded;       // cumulative KENO bonded (Law 6)

    // ─── Benford monitoring (Law 2) ───────────────────────────────────────────

    mapping(uint256 => uint256) public bondCountByBlock;  // block → bond count
    uint256 public totalBondCount;

    // ─── Events ──────────────────────────────────────────────────────────────

    event BondCreated(
        address indexed depositor,
        uint256 lpDeposited,
        uint256 kenoPayout,
        uint256 discount,
        bool    ramanujanBonus
    );
    event BondRedeemed(
        address indexed depositor,
        uint256 kenoRedeemed,
        uint256 kenoRemaining
    );
    event BcvAdjusted(uint256 oldBcv, uint256 newBcv, string direction);
    event KenoAllocated(uint256 amount, uint256 totalAvailable);
    event KenoWithdrawn(uint256 amount);

    // ─── Constructor ─────────────────────────────────────────────────────────

    /**
     * @param _kenoToken  KENO v2 contract address
     * @param _lpToken    KENO/BNB PancakeSwap LP token address
     * @param _treasury   Address that permanently receives LP tokens
     * @param _bcv        Initial Bond Control Variable (try 3_000_000 * 1e18 as starting point)
     * @param _bcvDecay   BCV decay rate in BPS per block when under-demanded (try 33 = 0.33%)
     * @param _targetDebtRatio  Target outstanding debt ratio in BPS (try 100 = 1% of supply)
     * @param _owner      Contract owner
     */
    constructor(
        address _kenoToken,
        address _lpToken,
        address _treasury,
        uint256 _bcv,
        uint256 _bcvDecay,
        uint256 _targetDebtRatio,
        address _owner
    ) Ownable(_owner) {
        require(_kenoToken != address(0), "Zero: kenoToken");
        require(_lpToken   != address(0), "Zero: lpToken");
        require(_treasury  != address(0), "Zero: treasury");
        require(_bcv > 0,                 "BCV must be > 0");

        kenoToken        = IERC20(_kenoToken);
        lpToken          = IERC20(_lpToken);
        treasury         = _treasury;
        bcv              = _bcv;
        bcvDecay         = _bcvDecay;
        targetDebtRatio  = _targetDebtRatio;
        lastBcvBlock     = block.number;
    }

    // ─── Core: Deposit ────────────────────────────────────────────────────────

    /**
     * @notice Bond KENO/BNB LP tokens for discounted KENO.
     *         LP tokens are sent permanently to the treasury.
     *         KENO payout vests linearly over VESTING_PERIOD.
     *
     * @param lpAmount     Amount of LP tokens to deposit (18 dec)
     * @param maxBondPrice Maximum bond price the caller will accept (slippage guard).
     *                     Bond price = KENO payout per unit of LP value (scaled ×1e18).
     *                     Use getBondPrice() to get current value before calling.
     * @param depositor    Address that will receive the vested KENO (usually msg.sender)
     */
    function deposit(
        uint256 lpAmount,
        uint256 maxBondPrice,
        address depositor
    ) external nonReentrant whenNotPaused {
        require(lpAmount > 0,          "LP amount must be > 0");
        require(depositor != address(0), "Zero depositor");

        _decayBcv();

        uint256 price = _bondPrice();
        require(price <= maxBondPrice, "Slippage: bond price too high");

        // Compute KENO payout from LP value
        uint256 lpValue  = _lpValue(lpAmount);         // LP valued in KENO units
        uint256 rawPayout = (lpValue * 1e18) / price;  // KENO to pay out

        // Safety: max payout cap (4% of available supply)
        uint256 cap = (kenoAvailable * MAX_PAYOUT_BPS) / BPS_BASE;
        require(rawPayout <= cap,           "Payout exceeds cap");
        require(rawPayout <= kenoAvailable, "Insufficient KENO available");

        // Law 6 — Ramanujan: silent 1.729% bonus if crossing 1729 KENO bonded
        bool ramanujanTriggered = false;
        uint256 payout = rawPayout;
        if (
            totalBonded[depositor] < RAMANUJAN_THRESHOLD &&
            totalBonded[depositor] + rawPayout >= RAMANUJAN_THRESHOLD
        ) {
            uint256 bonus = (rawPayout * RAMANUJAN_BONUS_BPS) / BPS_BASE;
            payout = rawPayout + bonus;
            if (payout > kenoAvailable) payout = kenoAvailable; // never exceed available
            ramanujanTriggered = true;
        }

        // Law 1 — Kaprekar: any dust (remainders from integer division) stays with depositor
        // payout is already rounded DOWN so the depositor gets the full integer share — no dust
        // is retained by the contract. Any wei-level remainder stays in kenoAvailable for next bond.

        // If the depositor already has an unvested bond, redeem it first
        if (bonds[depositor].payout > bonds[depositor].vested) {
            _redeem(depositor);
        }

        // Update state
        uint256 discount = _currentDiscount(price);
        totalBonded[depositor] += payout;
        kenoAvailable          -= payout;
        totalDebt              += payout;
        totalLpDeposited       += lpAmount;
        totalBondCount         += 1;
        bondCountByBlock[block.number] += 1; // Law 2 — Benford tracking

        bonds[depositor] = Bond({
            payout:       payout,
            vested:       0,
            lastRedeemed: block.timestamp,
            start:        block.timestamp
        });

        // Transfer LP to treasury permanently (Law 7 — Inversion)
        lpToken.safeTransferFrom(msg.sender, treasury, lpAmount);

        emit BondCreated(depositor, lpAmount, payout, discount, ramanujanTriggered);
    }

    // ─── Core: Redeem ─────────────────────────────────────────────────────────

    /**
     * @notice Claim all KENO that has vested since last redeem.
     *         Vesting is continuous (Law 5 — Euler): every second counts.
     * @param depositor Address whose bond to redeem
     */
    function redeem(address depositor) external nonReentrant returns (uint256) {
        return _redeem(depositor);
    }

    function _redeem(address depositor) internal returns (uint256 claimed) {
        Bond storage bond = bonds[depositor];
        uint256 remaining = bond.payout - bond.vested;
        if (remaining == 0) return 0;

        // Law 5 — Euler continuous vesting: accrual every second
        uint256 elapsed    = block.timestamp - bond.lastRedeemed;
        uint256 totalLeft  = VESTING_PERIOD > (block.timestamp - bond.start)
            ? VESTING_PERIOD - (block.timestamp - bond.start)
            : 0;

        uint256 claimable;
        if (totalLeft == 0 || elapsed >= VESTING_PERIOD) {
            // Fully vested — claim everything
            claimable = remaining;
        } else {
            // Linear proportion of remaining payout
            claimable = (remaining * elapsed) / (totalLeft + elapsed);
        }

        // Law 1 — Kaprekar: integer remainder stays with depositor on next call
        if (claimable == 0) return 0;

        bond.vested      += claimable;
        bond.lastRedeemed = block.timestamp;
        totalDebt        -= claimable;
        totalKenoPaid    += claimable;

        kenoToken.safeTransfer(depositor, claimable);

        emit BondRedeemed(depositor, claimable, bond.payout - bond.vested);
        return claimable;
    }

    // ─── View: Quotes & Prices ────────────────────────────────────────────────

    /**
     * @notice Current bond price: KENO payout per unit of LP value (×1e18).
     *         Lower price = bigger discount for the bonder.
     */
    function getBondPrice() external view returns (uint256) {
        return _bondPrice();
    }

    /**
     * @notice Current discount percentage in BPS (e.g. 500 = 5%).
     */
    function getCurrentDiscount() external view returns (uint256) {
        return _currentDiscount(_bondPrice());
    }

    /**
     * @notice Quote: how much KENO would `lpAmount` LP tokens bond for?
     * @return payout      KENO to be received (before Ramanujan bonus)
     * @return discount    Discount in BPS
     * @return price       Current bond price
     */
    function getBondQuote(uint256 lpAmount)
        external
        view
        returns (uint256 payout, uint256 discount, uint256 price)
    {
        price    = _bondPrice();
        discount = _currentDiscount(price);
        uint256 lpVal = _lpValue(lpAmount);
        payout   = lpVal > 0 ? (lpVal * 1e18) / price : 0;
        uint256 cap = (kenoAvailable * MAX_PAYOUT_BPS) / BPS_BASE;
        if (payout > cap) payout = cap;
    }

    /**
     * @notice How much KENO has vested and is claimable right now for a depositor.
     */
    function pendingPayout(address depositor) external view returns (uint256) {
        Bond storage bond = bonds[depositor];
        uint256 remaining = bond.payout - bond.vested;
        if (remaining == 0) return 0;

        uint256 elapsed   = block.timestamp - bond.lastRedeemed;
        uint256 totalLeft = VESTING_PERIOD > (block.timestamp - bond.start)
            ? VESTING_PERIOD - (block.timestamp - bond.start)
            : 0;

        if (totalLeft == 0 || elapsed >= VESTING_PERIOD) return remaining;
        return (remaining * elapsed) / (totalLeft + elapsed);
    }

    /**
     * @notice True if depositor is eligible for the Ramanujan bonus on their next bond.
     */
    function isRamanujanEligible(address depositor) external view returns (bool) {
        return totalBonded[depositor] < RAMANUJAN_THRESHOLD;
    }

    /**
     * @notice Current outstanding debt ratio vs kenoAvailable (BPS).
     */
    function debtRatio() external view returns (uint256) {
        if (kenoAvailable == 0) return 0;
        return (totalDebt * BPS_BASE) / kenoAvailable;
    }

    // ─── Internal: BCV & Pricing ──────────────────────────────────────────────

    /**
     * @dev Bond price = BCV × debtRatio / 1e18
     *      Clamped so discount stays in [MIN_DISCOUNT_BPS, MAX_DISCOUNT_BPS].
     *      Law 4 — Nash: BCV self-tunes to keep discount in equilibrium window.
     */
    function _bondPrice() internal view returns (uint256 price) {
        uint256 supply = kenoToken.totalSupply();
        if (supply == 0) return 1e18;

        uint256 debt   = totalDebt;
        uint256 ratio  = debt > 0 ? (debt * 1e18) / supply : 1;
        price = (bcv * ratio) / 1e18;
        if (price == 0) price = 1;

        // Clamp: ensure discount stays within constitutional window
        // marketPrice (1:1 in LP-value terms) is 1e18 by convention
        uint256 maxPrice = (1e18 * BPS_BASE) / (BPS_BASE - MIN_DISCOUNT_BPS); // min discount floor
        uint256 minPrice = (1e18 * BPS_BASE) / (BPS_BASE - MAX_DISCOUNT_BPS); // max discount cap
        if (price > maxPrice) price = maxPrice;
        if (price < minPrice) price = minPrice;
    }

    /**
     * @dev Compute discount in BPS given a bond price.
     *      discount = (1 - 1/price) × 10000   (price is ×1e18 vs market)
     *      Simplified: discount = (price - 1e18) × BPS_BASE / price
     */
    function _currentDiscount(uint256 price) internal pure returns (uint256) {
        if (price <= 1e18) return 0;
        return ((price - 1e18) * BPS_BASE) / price;
    }

    /**
     * @dev Law 4 — Nash: decay BCV when bond demand is below target debt ratio.
     *      Lower BCV → lower bond price → higher discount → stimulates demand.
     *      Raise BCV when demand is above target → discount shrinks → equilibrium.
     */
    function _decayBcv() internal {
        uint256 blockDelta = block.number - lastBcvBlock;
        if (blockDelta == 0) return;
        lastBcvBlock = block.number;

        uint256 supply  = kenoToken.totalSupply();
        if (supply == 0) return;

        uint256 currentRatio = totalDebt > 0 ? (totalDebt * BPS_BASE) / supply : 0;

        if (currentRatio < targetDebtRatio) {
            // Under-demanded: decay BCV (widens discount, attracts bonders)
            uint256 decay   = (bcv * bcvDecay * blockDelta) / BPS_BASE;
            uint256 oldBcv  = bcv;
            uint256 floor   = 1e18; // never decay below 1 (Law 3 — φ minimum)
            bcv = bcv > decay + floor ? bcv - decay : floor;
            if (bcv != oldBcv) emit BcvAdjusted(oldBcv, bcv, "decay");
        } else if (currentRatio > targetDebtRatio * 2) {
            // Over-demanded: raise BCV (shrinks discount, reduces KENO outflow)
            uint256 bump   = (bcv * bcvDecay * blockDelta) / BPS_BASE;
            uint256 oldBcv = bcv;
            bcv += bump;
            emit BcvAdjusted(oldBcv, bcv, "raise");
        }
    }

    /**
     * @dev LP value expressed in KENO units.
     *      Simplified: 1 LP token = 2 × sqrt(kenoReserve × bnbReserve) / totalSupply × kenoPerBnb
     *      For a BSC deployment without an oracle, we use the LP contract's reserves directly.
     *      Returns value in KENO wei (18 dec).
     */
    function _lpValue(uint256 lpAmount) internal view returns (uint256) {
        IPancakePair pair = IPancakePair(address(lpToken));
        (uint112 r0, uint112 r1,) = pair.getReserves();
        uint256 lpSupply = pair.totalSupply();
        if (lpSupply == 0) return 0;

        address token0 = pair.token0();
        // Determine which reserve is KENO
        uint256 kenoReserve = (token0 == address(kenoToken))
            ? uint256(r0)
            : uint256(r1);

        // LP value in KENO = 2 × kenoReserve × lpAmount / lpSupply
        // (both sides of the pool contribute equally in a balanced AMM)
        return (2 * kenoReserve * lpAmount) / lpSupply;
    }

    // ─── Owner: Administration ────────────────────────────────────────────────

    /**
     * @notice Deposit KENO into this contract to fund bond payouts.
     *         Owner must approve first.
     */
    function allocateKeno(uint256 amount) external onlyOwner {
        require(amount > 0, "Zero amount");
        kenoAvailable += amount;
        kenoToken.safeTransferFrom(msg.sender, address(this), amount);
        emit KenoAllocated(amount, kenoAvailable);
    }

    /**
     * @notice Withdraw unallocated KENO (not owed to any active bond).
     */
    function withdrawKeno(uint256 amount) external onlyOwner {
        uint256 free = kenoAvailable; // totalDebt is tracked separately from kenoAvailable
        require(amount <= free, "Exceeds free KENO");
        kenoAvailable -= amount;
        kenoToken.safeTransfer(owner(), amount);
        emit KenoWithdrawn(amount);
    }

    function setBcv(uint256 _bcv) external onlyOwner {
        require(_bcv > 0, "BCV must be > 0");
        uint256 old = bcv;
        bcv = _bcv;
        emit BcvAdjusted(old, _bcv, "manual");
    }

    function setBcvDecay(uint256 _decay) external onlyOwner {
        require(_decay <= 500, "Decay max 5% per block");
        bcvDecay = _decay;
    }

    function setTargetDebtRatio(uint256 _ratio) external onlyOwner {
        require(_ratio <= 2_000, "Max 20%");
        targetDebtRatio = _ratio;
    }

    function pause()   external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }

    // ─── Law 2: Benford Monitoring ────────────────────────────────────────────

    /**
     * @notice Returns bond volume for a range of blocks.
     *         Owner uses this to detect anomalous patterns (front-running, wash bonds).
     */
    function getBondVolume(uint256 fromBlock, uint256 toBlock)
        external
        view
        returns (uint256 volume)
    {
        for (uint256 b = fromBlock; b <= toBlock; b++) {
            volume += bondCountByBlock[b];
        }
    }
}

// ─── Interfaces ────────────────────────────────────────────────────────────────

interface IPancakePair {
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function totalSupply() external view returns (uint256);
    function token0() external view returns (address);
}

contracts/KenostodNode.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * Kenostod Network Node NFT
 *
 * Each node entitles the holder to a proportional share of 10% of the
 * Kenostod arb bot fleet's daily profits, distributed by the bot wallet.
 *
 * Max supply  : 20 nodes
 * Price       : 0.5 BNB per node
 * Proceeds    : forwarded to bot wallet (treasury) on each mint
 */

interface IERC721Receiver {
    function onERC721Received(address, address, uint256, bytes calldata) external returns (bytes4);
}

// WBNB on BSC: 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c
contract KenostodNode {
    // ── ERC-721 storage ───────────────────────────────────────────────────────
    string public name     = "Kenostod Network Node";
    string public symbol   = "KNODE";
    uint256 public totalSupply;

    mapping(uint256 => address) private _owners;
    mapping(address => uint256) private _balances;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    // ── Node sale config ──────────────────────────────────────────────────────
    uint256 public constant MAX_NODES   = 20;
    uint256 public constant NODE_PRICE  = 0.5 ether;  // 0.5 BNB
    uint256 public constant NODE_YIELD_PCT = 10;       // 10% of daily bot profits
    address public immutable treasury;                 // bot wallet receives proceeds
    address public owner;

    bool public saleOpen = true;

    // ── Node metadata ─────────────────────────────────────────────────────────
    mapping(uint256 => uint256) public mintedAt;   // block timestamp of mint

    // ── Events ────────────────────────────────────────────────────────────────
    event Transfer(address indexed from, address indexed to, uint256 indexed tokenId);
    event Approval(address indexed owner_, address indexed approved, uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner_, address indexed operator, bool approved);
    event NodeMinted(uint256 indexed tokenId, address indexed buyer, uint256 price);
    event SaleToggled(bool open);

    // ── Modifiers ─────────────────────────────────────────────────────────────
    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    // ── Constructor ───────────────────────────────────────────────────────────
    constructor(address _treasury) {
        owner    = msg.sender;
        treasury = _treasury;
    }

    // ── Sale ──────────────────────────────────────────────────────────────────
    function mintNode() external payable {
        require(saleOpen,                          "Sale closed");
        require(totalSupply < MAX_NODES,           "All 20 nodes sold");
        require(msg.value == NODE_PRICE,           "Send exactly 0.5 BNB");

        totalSupply++;
        uint256 tokenId = totalSupply;

        _owners[tokenId]    = msg.sender;
        _balances[msg.sender]++;
        mintedAt[tokenId]   = block.timestamp;

        // Forward BNB to treasury immediately
        (bool sent, ) = treasury.call{value: msg.value}("");
        require(sent, "BNB transfer failed");

        emit Transfer(address(0), msg.sender, tokenId);
        emit NodeMinted(tokenId, msg.sender, msg.value);
    }

    function toggleSale() external onlyOwner {
        saleOpen = !saleOpen;
        emit SaleToggled(saleOpen);
    }

    // ── Node info ─────────────────────────────────────────────────────────────
    function nodesRemaining() external view returns (uint256) {
        return MAX_NODES - totalSupply;
    }

    function nodesByOwner(address holder) external view returns (uint256[] memory) {
        uint256 count = _balances[holder];
        uint256[] memory ids = new uint256[](count);
        uint256 idx;
        for (uint256 i = 1; i <= totalSupply; i++) {
            if (_owners[i] == holder) {
                ids[idx++] = i;
            }
        }
        return ids;
    }

    // ── ERC-721 core ──────────────────────────────────────────────────────────
    function balanceOf(address holder) external view returns (uint256) {
        return _balances[holder];
    }

    function ownerOf(uint256 tokenId) external view returns (address) {
        address o = _owners[tokenId];
        require(o != address(0), "Nonexistent token");
        return o;
    }

    function approve(address to, uint256 tokenId) external {
        address o = _owners[tokenId];
        require(msg.sender == o || _operatorApprovals[o][msg.sender], "Not authorized");
        _tokenApprovals[tokenId] = to;
        emit Approval(o, to, tokenId);
    }

    function getApproved(uint256 tokenId) external view returns (address) {
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external {
        _operatorApprovals[msg.sender][operator] = approved;
        emit ApprovalForAll(msg.sender, operator, approved);
    }

    function isApprovedForAll(address holder, address operator) external view returns (bool) {
        return _operatorApprovals[holder][operator];
    }

    function transferFrom(address from, address to, uint256 tokenId) public {
        require(_owners[tokenId] == from,                                     "Wrong owner");
        require(to != address(0),                                             "Zero address");
        require(
            msg.sender == from ||
            _tokenApprovals[tokenId] == msg.sender ||
            _operatorApprovals[from][msg.sender],
            "Not authorized"
        );
        _balances[from]--;
        _balances[to]++;
        _owners[tokenId]         = to;
        _tokenApprovals[tokenId] = address(0);
        emit Transfer(from, to, tokenId);
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external {
        safeTransferFrom(from, to, tokenId, "");
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public {
        transferFrom(from, to, tokenId);
        if (to.code.length > 0) {
            bytes4 ret = IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data);
            require(ret == IERC721Receiver.onERC721Received.selector, "Not ERC721Receiver");
        }
    }

    function supportsInterface(bytes4 interfaceId) external pure returns (bool) {
        return
            interfaceId == 0x80ac58cd || // ERC721
            interfaceId == 0x01ffc9a7;  // ERC165
    }

    // ── Token URI (on-chain SVG) ───────────────────────────────────────────────
    function tokenURI(uint256 tokenId) external view returns (string memory) {
        require(_owners[tokenId] != address(0), "Nonexistent token");
        return string(abi.encodePacked(
            'data:application/json;utf8,{"name":"Kenostod Node #', _toString(tokenId),
            '","description":"Kenostod Network Node - earns 10% of daily arb bot profits proportionally among all 20 nodes.",',
            '"image":"data:image/svg+xml;utf8,<svg xmlns=\\"http://www.w3.org/2000/svg\\" viewBox=\\"0 0 300 300\\">',
            '<rect width=\\"300\\" height=\\"300\\" fill=\\"#0d1117\\"/>',
            '<text x=\\"150\\" y=\\"120\\" font-family=\\"monospace\\" font-size=\\"14\\" fill=\\"#667eea\\" text-anchor=\\"middle\\">KENOSTOD</text>',
            '<text x=\\"150\\" y=\\"155\\" font-family=\\"monospace\\" font-size=\\"36\\" fill=\\"#f6ad55\\" text-anchor=\\"middle\\">NODE</text>',
            '<text x=\\"150\\" y=\\"185\\" font-family=\\"monospace\\" font-size=\\"18\\" fill=\\"#48bb78\\" text-anchor=\\"middle\\">#', _toString(tokenId),
            '</text><text x=\\"150\\" y=\\"220\\" font-family=\\"monospace\\" font-size=\\"11\\" fill=\\"#94a3b8\\" text-anchor=\\"middle\\">10% Daily Bot Profits</text>',
            '</svg>","attributes":[{"trait_type":"Node ID","value":', _toString(tokenId),
            '},{"trait_type":"Yield Share","value":"10% / 20 nodes"}]}'
        ));
    }

    function _toString(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 tmp = v;
        uint256 digits;
        while (tmp != 0) { digits++; tmp /= 10; }
        bytes memory buf = new bytes(digits);
        while (v != 0) { digits--; buf[digits] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(buf);
    }
}

